#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals euclidean_geometry eqtype. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Section square_quadrilaterals. Variable R : realType. Record point := Point { px : R; py : R }. Definition colinear (A B C : point) : Prop := (px B - px A) * (py C - py A) = (py B - py A) * (px C - px A). Definition perpendicular (A B C D : point) : Prop := let u1 := (px B - px A, py B - py A) in let u2 := (px D - px C, py D - py C) in u1.1 * u2.1 + u1.2 * u2.2 = 0. Definition segment_length (A B : point) : R := sqrt ((px A - px B)^2 + (py A - py B)^2). Variable S : R. Hypothesis Spos : S > 0. Variable A B C D E F G H P : point. Hypothesis square_ABCD : segment_length A B = segment_length B C /\ segment_length B C = segment_length C D /\ segment_length C D = segment_length D A /\ perpendicular A B C D. Theorem segment_property : segment_length A B = sqrt S. Proof. Admitted. End
